<script setup>
import { onMounted, ref, computed } from 'vue'; import { getMyTasks } from '../../api/wms'; const list=ref([]); const active=ref('all'); const names={PICKING:'拣货',PUTAWAY:'上架',COUNTING:'盘点',REPLENISHMENT:'补货'}; const visible=computed(()=>active.value==='all'?list.value:list.value.filter(i=>i.status===active.value)); onMounted(async()=>list.value=await getMyTasks())
</script>
<template><div><header class="mobile-page-head"><h1>我的任务</h1><p>按优先级与要求完成时间排序</p><div class="task-tabs"><button :class="{active:active==='all'}" @click="active='all'">全部 3</button><button :class="{active:active==='IN_PROGRESS'}" @click="active='IN_PROGRESS'">作业中 1</button><button :class="{active:active==='WAITING'}" @click="active='WAITING'">待领取 2</button></div></header><main class="mobile-content"><article v-for="t in visible" :key="t.id" class="task-card"><div class="task-card-top"><div><span class="task-type">{{names[t.type]}}</span><span v-if="t.priority!=='NORMAL'" class="urgent">{{t.priority==='URGENT'?'紧急':'高优先级'}}</span></div><time>{{t.dueAt.slice(11,16)}} 前</time></div><h3>{{t.productName}}</h3><p class="sku">任务 {{t.taskNo}} · 数量 {{t.plannedQty}}</p><div class="task-route"><div><span>从</span><strong>{{t.sourceLocation}}</strong></div><i>→</i><div><span>到</span><strong>{{t.targetLocation||'原库位'}}</strong></div></div><div class="task-card-actions"><button>查看明细</button><button class="primary">{{t.status==='IN_PROGRESS'?'继续作业':'领取任务'}}</button></div></article></main></div></template>
